es.length" class="mt-1"><v-col v-for="candidate in promptCandidates" :key="candidate.model" cols="12" :md="promptCandidates.length > 1 ? 6 : 12"><v-card variant="outlined" class="prompt-candidate h-100"><v-card-text><div class="d-flex align-center justify-space-between ga-3"><div><strong>{{ candidate.model }}</strong><p v-if="candidate.summary">{{ candidate.summary }}</p></div><v-btn color="success" size="small" @click="applyPromptCandidate(candidate)">应用此候选</v-btn></div><v-alert v-if="candidate.assumptions?.length" type="info" variant="tonal" density="compact" class="my-3">{{ candidate.assumptions.join('；') }}</v-alert><v-textarea v-model="candidate.system_prompt" label="System Prompt" rows="4" auto-grow class="mt-3"/><v-textarea v-model="candidate.analysis_prompt_template" label="分析提示词模板" rows="10" auto-grow class="mt-2"/></v-card-text></v-card></v-col></v-row></div></v-col>
