<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { marketAPI } from '@/api/market'

const periods = ['M1', 'M5', 'M15', 'H1', 'H4']
const sourceVersions = [{ title: '2.0 结构化模板', value: '2.0' }, { title: '1.0 自定义提示词', value: '1.0' }]
const structureTemplates = [{ title: '自动识别：背景趋势 + 动态局部结构', value: 'auto_structure' }, { title: '箱体优先', value: 'range' }, { title: '趋势回调优先', value: 'trend_pullback' }, { title: '收敛三角形', value: 'converging_triangle' }, { title: '扩散三角形', value: 'diverging_triangle' }]
const horizonOptions = [{ title: '自动', value: 0 }, ...[6, 10, 20, 30, 48].map(value => ({ title: `${value} 根`, value }))]
const defaultPromptIntent = '识别主周期趋势、行情状态和关键支撑压力位，并输出可由实时 Tick 后续评估的结构化交易计划：区间在边界交易，趋势在回调或反抽时顺势交易。'
const defaultSystemPrompt = '你是一位专业的技术分析师。只能依据提供的主品种、主周期 K 线判断趋势、关键价位和交易机会；参考行情只能辅助确认，不能独立产生结论。只返回严格、完整的 JSON 对象，不得输出解释、推理过程或 Markdown。交易建议必须遵守模板字段与价格规则；只有条件不足以形成可辩护的结构化交易计划时才返回空数组。'
const defaultAnalysisPromptTemplate = '请分析主品种的主周期 K 线，只返回严格 JSON，顶层键必须为实际主品种名称。\n\n主行情 K 线：\n{{market_data}}\n\n当前可交易参考价：\n{{current_price}}\n当前价格只用于理解市场位置和风险，不要求 entry_price 接近当前价；策略会在后续实时 Tick 接近 entry_price 时再评估入场。\n\n可选参考行情：\n{{reference_market_data}}\n参考行情为空时忽略本节；它只能辅助主行情判断，不能单独产生趋势或交易建议。\n\n规则：\n1. 必须输出主周期的 trend_analysis、overall_trend、key_levels 和 trade_suggestions。\n2. trade_suggestions 是由 K 线结构得出的未来价格计划；只有不存在可辩护计划时才返回 []。\n3. 区间震荡：可在确认支撑附近给 buy、确认压力附近给 sell；止损放在区间外，止盈指向另一侧。即使当前价格在区间中部，仍可给出这些未来边界计划。\n4. 单边上涨：在上涨结构未失效时，可给出回调或回踩至趋势线/支撑的 buy 计划；stop_loss 放在结构失效位下方，take_profit 指向趋势延续目标。\n5. 单边下跌：在下跌结构未失效时，可给出反抽至压力/趋势线的 sell 计划；stop_loss 放在结构失效位上方，take_profit 指向趋势延续目标。\n6. buy 必须满足 stop_loss < entry_price < take_profit；sell 必须满足 take_profit < entry_price < stop_loss。\n\n输出：\n{"实际主品种":{"trend_analysis":{"主周期":{"trend":"趋势类型","confidence":68,"reason":"K线判断理由"}},"overall_trend":{"direction":"up|down|sideways","strength":0,"summary":"行情结论"},"key_levels":{"resistance":[0,0,0],"support":[0,0,0]},"trade_suggestions":[{"signal_source_id":"当前信号源ID","period":"主周期","direction":"buy|sell","confidence":68,"entry_price":0,"stop_loss":0,"take_profit":0,"reason":"结构化交易计划理由"}]}}\n不要输出 Markdown、思考过程、策略 ID 或额外字段。'
const defaultPromptCandidate = () => ({ model: '结构化交易计划默认候选', system_prompt: defaultSystemPrompt, analysis_prompt_template: defaultAnalysisPromptTemplate, summary: '基于主周期趋势、关键价位和未来入场计划的通用模板，可由策略在后续实时 Tick 中评估。', assumptions: ['只分析主品种和主周期', '参考行情仅辅助主行情判断', '没有可辩护的结构化计划时才返回空交易建议'] })
const sources = ref([]), loading = ref(false), saving = ref(false), dialog = ref(false), message = ref(''), messageType = ref('success'), loadingOptions = ref(false), generatingPrompt = ref(false), pausingId = ref(''), adaptiveId = ref(''), promptIntent = ref(defaultPromptIntent), promptModels = ref([]), promptCandidates = ref([])
const options = reactive({ models: [], promptGenerationModels: [], symbols: [], marketDataAccounts: [], system: '', prompt: '', runtimeContract: { runtime_variables: [], output_contract: {}, strategy_usage: [] } })
const emptyForm = () => ({ signal_source_id: '', name: '', market_data_account_id: 0, symbol: '', period: 'M5', enabled: true, share_runtime_data: false, config: { signal_source_version: '2.0', analysis_template: 'auto_structure', analysis_mode: 'self_analysis', model: '', analysis_interval_minutes: 5, forecast_horizon_bars: 0, kline_count: 288, range_min_touches: 3, range_min_inside_ratio: 0.80, range_tolerance_atr_multiplier: 0.60, range_tolerance_width_ratio: 0.02, range_min_width_atr: 2, range_max_width_atr: 6, adaptive_enabled: true, adaptive_sample_size: 7, prompt_mode: 'structured', reference_runtime_ids: [], reference_market_data: [], system_prompt: defaultSystemPrompt, analysis_prompt_template: defaultAnalysisPromptTemplate } })
const form = reactive(emptyForm())
const rangeInsidePercent = computed({ get: () => Math.round(Number(form.config.range_min_inside_ratio || 0.80) * 100), set: value => { form.config.range_min_inside_ratio = Number(value || 80) / 100 } })
const rangeToleranceWidthPercent = computed({ get: () => Number(form.config.range_tolerance_width_ratio || 0.02) * 100, set: value => { form.config.range_tolerance_width_ratio = Number(value || 2) / 100 } })
const intervalOptions = computed(() => [1,2,3,5,10,15,30,60,120,240,480,720,1440].filter(value => value >= ({ M1: 1, M5: 5, M15: 15, H1: 60, H4: 240 }[form.period] || 1)).map(value => ({ title: `${value} 分钟`, value })))
const referenceRoles = [{ title: '高周期确认', value: 'higher_timeframe' }, { title: '低周期确认', value: 'lower_timeframe' }, { title: '相关品种', value: 'related_symbol' }, { title: '市场上下文', value: 'market_context' }]
const references = computed(() => form.config.reference_market_data || [])
const automaticBackgroundPeriods = computed(() => ({
  M1: ['M5', 'M15'],
  M5: ['M15', 'H1'],
  M15: ['H1', 'H4'],
  H1: ['H4'],
  H4: [],
}[form.period] || []))
// 同品种的其他周期也是有效的参考行情；只有同品种时排除主分析周期。
const referenceSymbols = computed(() => Array.from(new Set([form.symbol, ...options.symbols].filter(Boolean))))
function referencePeriodOptions (reference) {
  const current = String(reference?.period || '')
  const isSameSymbol = String(reference?.symbol || '').trim().toUpperCase() === String(form.symbol || '').trim().toUpperCase()
  return periods.filter(period => !isSameSymbol || period !== form.period || period === current)
}
const canGeneratePrompt = computed(() => form.config.signal_source_version === '1.0' && Boolean(form.symbol && form.period && promptIntent.value.trim() && promptModels.value.length <= 3))
const clone = value => JSON.parse(JSON.stringify(value))
async function load () { loading.value = true; try { sources.value = (await marketAPI.getAISignalSources()).items || [] } catch (e) { messageType.value='error'; message.value=e.response?.data?.detail || '加载信号源失败' } finally { loading.value=false } }
async function loadOptions () { loadingOptions.value=true; try { const data=await marketAPI.getLLMSignalOptions(form.symbol || null); options.models=data.models||[]; options.promptGenerationModels=data.prompt_generation_models||[]; options.symbols=data.symbols||[]; form.market_data_account_id=0; options.system=data.default_system_prompt||''; options.prompt=data.default_analysis_prompt_template||''; options.runtimeContract=data.runtime_contract || { runtime_variables: [], output_contract: {}, strategy_usage: [] } } finally { loadingOptions.value=false } }
function openCreate (version = '2.0') { Object.assign(form, emptyForm()); form.config.signal_source_version=version; form.config.analysis_template=version === '2.0' ? 'auto_structure' : 'custom'; form.config.prompt_mode=version === '2.0' ? 'structured' : 'custom'; promptIntent.value=defaultPromptIntent; promptModels.value=[]; promptCandidates.value=version === '1.0' ? [defaultPromptCandidate()] : []; dialog.value=true; loadOptions() }
function openEdit (item) { Object.assign(form, clone(item)); form.config ||= {}; form.config.signal_source_version ||= '1.0'; form.config.analysis_template ||= form.config.signal_source_version === '2.0' ? 'auto_structure' : 'custom'; form.config.forecast_horizon_bars = Number(form.config.forecast_horizon_bars || 0); form.config.range_min_touches = Number(form.config.range_min_touches || 3); form.config.range_min_inside_ratio = Number(form.config.range_min_inside_ratio || 0.80); form.config.range_tolerance_atr_multiplier = Number(form.config.range_tolerance_atr_multiplier || 0.60); form.config.range_tolerance_width_ratio = Number(form.config.range_tolerance_width_ratio || 0.02); form.config.range_min_width_atr = Number(form.config.range_min_width_atr || 2); form.config.range_max_width_atr = Number(form.config.range_max_width_atr || 6); form.config.adaptive_enabled = form.config.adaptive_enabled !== false; form.config.adaptive_sample_size = Number(form.config.adaptive_sample_size || 7); form.config.reference_market_data ||= []; form.config.prompt_mode=form.config.signal_source_version === '2.0' ? 'structured' : 'custom'; promptIntent.value=defaultPromptIntent; promptModels.value=[]; const currentCandidate = { model: form.config.signal_source_version === '1.0' ? '1.0 默认模板（可编辑）' : '2.0 系统模板', system_prompt: form.config.system_prompt || defaultSystemPrompt, analysis_prompt_template: form.config.analysis_prompt_template || defaultAnalysisPromptTemplate, summary: form.config.signal_source_version === '1.0' ? '系统默认 1.0 模板，可直接修改后保存。' : '系统内置结构化模板。', assumptions: [] }; promptCandidates.value=form.config.signal_source_version === '2.0' ? [] : [currentCandidate]; dialog.value=true; loadOptions() }
function normalizeReferencePeriod (reference) {
  if (!reference || String(reference.symbol || '').trim().toUpperCase() !== String(form.symbol || '').trim().toUpperCase()) return
  if (reference.period !== form.period) return
  reference.period = periods.find(period => period !== form.period) || form.period
}
function addReference () {
  if (references.value.length >= 5) return
  const symbol = form.symbol || referenceSymbols.value[0] || ''
  const period = periods.find(value => value !== form.period) || form.period
  references.value.push({ symbol, period, kline_count: 100, role: 'market_context' })
}
function removeReference (index) { references.value.splice(index, 1) }
async function generatePrompt () { generatingPrompt.value=true; try { const data=clone(form); data.config.reference_market_data=(data.config.reference_market_data || []).filter(item => item.symbol && item.period); const result=await marketAPI.generateAISignalPrompt({ ...data, intent: promptIntent.value.trim(), model_ids: promptModels.value }); promptCandidates.value=result.candidates || (result.candidate ? [result.candidate] : []); messageType.value='success'; message.value=promptCandidates.value.length > 1 ? '已生成多个提示词候选，请对比后选择一份应用。' : '已根据当前信号源配置生成候选提示词，请预览后应用。' } catch(e) { messageType.value='error'; message.value=e.response?.data?.detail || '生成提示词候选失败' } finally { generatingPrompt.value=false } }
function applyPromptCandidate (candidate) { if (!candidate) return; form.config.prompt_mode='custom'; form.config.system_prompt=candidate.system_prompt; form.config.analysis_prompt_template=candidate.analysis_prompt_template; messageType.value='success'; message.value=`已应用 ${candidate.model || '候选'}，保存信号源后生效。` }
function syncLegacyPrompt () { const candidate = promptCandidates.value[0]; if (form.config.signal_source_version === '1.0' && candidate) { form.config.system_prompt = candidate.system_prompt; form.config.analysis_prompt_template = candidate.analysis_prompt_template } }
async function save () { saving.value=true; try { syncLegacyPrompt(); const data=clone(form); const minimum={M1:1,M5:5,M15:15,H1:60,H4:240}[data.period]||1; data.config.analysis_mode='self_analysis'; data.config.signal_source_version=data.config.signal_source_version || '2.0'; data.config.analysis_template=data.config.analysis_template || 'auto_structure'; data.config.analysis_interval_minutes=Math.max(minimum, Number(data.config.analysis_interval_minutes) || 0); data.config.kline_count=Math.max(10, Math.min(288, Number(data.config.kline_count) || 100)); data.config.range_min_touches=Math.max(1, Math.min(5, Number(data.config.range_min_touches) || 3)); data.config.range_min_inside_ratio=Math.max(0.5, Math.min(1, Number(data.config.range_min_inside_ratio) || 0.80)); data.config.range_tolerance_atr_multiplier=Math.max(0.1, Math.min(3, Number(data.config.range_tolerance_atr_multiplier) || 0.60)); data.config.range_tolerance_width_ratio=Math.max(0.005, Math.min(0.2, Number(data.config.range_tolerance_width_ratio) || 0.02)); data.config.range_min_width_atr=Math.max(0, Math.min(20, Number(data.config.range_min_width_atr) || 2)); data.config.range_max_width_atr=Math.max(data.config.range_min_width_atr, Math.min(50, Number(data.config.range_max_width_atr) || 6)); data.config.adaptive_enabled=data.config.adaptive_enabled !== false; data.config.adaptive_sample_size=Math.max(5, Math.min(50, Number(data.config.adaptive_sample_size) || 7)); data.config.reference_market_data=(data.config.reference_market_data || []).filter(item => item.symbol && item.period).map(item => ({ ...item, kline_count: Math.max(10, Math.min(288, Number(item.kline_count) || 100)) })); data.config.prompt_mode=data.config.signal_source_version === '2.0' ? 'structured' : 'custom'; if (data.config.signal_source_version === '1.0' && (!data.config.system_prompt || !data.config.analysis_prompt_template)) throw new Error('1.0 默认提示词初始化失败，请重试'); const result=data.signal_source_id ? await marketAPI.updateAISignalSource(data.signal_source_id,data) : await marketAPI.createAISignalSource(data); dialog.value=false; messageType.value='success'; message.value=result.source?.locked ? '已保存并冻结' : 'AI 信号源已保存'; await load() } catch(e) { messageType.value='error'; message.value=e.response?.data?.detail || '保存失败' } finally { saving.value=false } }
async function toggleAdaptive (item) { adaptiveId.value=item.signal_source_id; try { const enabled=item.config?.adaptive_enabled === false; await marketAPI.configureAISignalAdaptive(item.signal_source_id,enabled,item.config?.adaptive_sample_size||7); messageType.value='success'; message.value=`自适应调参已${enabled?'开启':'关闭'}并热加载`; await load() } catch(e) { messageType.value='error'; message.value=e.response?.data?.detail||'调整自适应设置失败' } finally { adaptiveId.value='' } }
async function copy (item) { try { await marketAPI.copyAISignalSource(item.signal_source_id); messageType.value='success'; message.value='已创建可修改的新副本'; await load() } catch(e) { messageType.value='error'; message.value=e.response?.data?.detail || '复制失败' } }
async function togglePause (item) {
  const paused = !item.config?.analysis_paused
  if (!paused) {
    pausingId.value = item.signal_source_id
    try { await marketAPI.pauseAISignalSource(item.signal_source_id, false); messageType.value='success'; message.value='AI 行情分析已恢复'; await load() } catch (e) { messageType.value='error'; message.value=e.response?.data?.detail || '恢复分析失败' } finally { pausingId.value='' }
    return
  }
  try {
    const impact = await marketAPI.getAISignalSourceImpact(item.signal_source_id)
    const rows = impact.items || []
    const users = Array.from(new Set(rows.map(row => row.username).filter(Boolean)))
    const strategies = rows.map(row => `${row.strategy_name || row.strategy_id}（${row.execution_mode === 'live' ? '实盘' : '模拟盘'}，${row.username || '未知用户'}，${row.deployment_status === 'active' ? '运行中' : row.deployment_status === 'paused' ? '已暂停' : '已结束'}）`)
    const detail = strategies.length ? `\n\n受影响策略：\n${strategies.join('\n')}` : '\n\n当前没有已部署策略引用此信号源。'
    if (!window.confirm(`暂停“${item.name}”的 AI 行情分析？\n\n将停止后续大模型分析和策略消费，已有分析快照保留。\n受影响用户：${users.length ? users.join('、') : '无'}${detail}`)) return
    pausingId.value = item.signal_source_id
    await marketAPI.pauseAISignalSource(item.signal_source_id, true)
    messageType.value='success'; message.value='AI 行情分析已暂停，影响范围已记录'; await load()
  } catch (e) { messageType.value='error'; message.value=e.response?.data?.detail || '暂停分析失败' } finally { pausingId.value='' }
}
async function remove (item) { if (!confirm(`删除“${item.name}”吗？`)) return; try { await marketAPI.deleteAISignalSource(item.signal_source_id); await load() } catch(e) { messageType.value='error'; message.value=e.response?.data?.detail || '删除失败' } }
watch(() => form.period, () => { const minimum={M1:1,M5:5,M15:15,H1:60,H4:240}[form.period]||1; form.config.analysis_interval_minutes=Math.max(Number(form.config.analysis_interval_minutes)||0, minimum) })
onMounted(load)
</script>

